const ctx = $json;
const tenantPhone = String(ctx.tenant?.phone || '').replace(/\D/g, '');
const senderPhone = String(ctx.sender_phone || '').replace(/\D/g, '');
const isOwner = tenantPhone && senderPhone && tenantPhone.endsWith(senderPhone.slice(-9));
return [{ json: { ...ctx, actor: isOwner ? 'owner' : 'customer', is_owner: isOwner } }];
